:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --text: #e0e0e0;
  --accent: #e94560;
  --accent-hover: #ff6b81;
  --border: #0f3460;
  --correct: #4ecca3;
  --wrong: #e94560;
  --disabled: #4a4a6a;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: 'Courier New', monospace;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  font-size: 16px;
}

.quiz-card {
  background: var(--card);
  border: 4px solid var(--border);
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0,0,0,0.3);
}

h1 {
  font-size: 28px;
  margin-bottom: 16px;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 2px;
}

.question {
  font-size: 36px;
  margin: 24px 0;
  font-weight: bold;
  min-height: 1.2em;
}

.answers {
  display: flex;
  gap: 16px;
  justify-content: center;
  margin: 24px 0;
  flex-wrap: wrap;
}

.answer, .control {
  font-family: inherit;
  font-size: 20px;
  padding: 12px 24px;
  border: 3px solid var(--border);
  background: var(--bg);
  color: var(--text);
  cursor: pointer;
  transition: background 0.1s, transform 0.1s;
  min-width: 80px;
}

.answer:hover:not(:disabled), .control:hover:not(:disabled) {
  background: var(--accent-hover);
  color: var(--bg);
}

.answer:focus-visible, .control:focus-visible {
  outline: 3px solid var(--accent);
  outline-offset: 2px;
}

.answer:active:not(:disabled), .control:active:not(:disabled) {
  transform: translate(2px, 2px);
}

.answer:disabled, .control:disabled {
  opacity: 0.5;
  cursor: not-allowed;
  background: var(--disabled);
}

.answer.correct {
  background: var(--correct);
  color: var(--bg);
  border-color: var(--correct);
}

.answer.wrong {
  background: var(--wrong);
  color: var(--bg);
  border-color: var(--wrong);
}

.score-line {
  font-size: 24px;
  margin: 16px 0;
}

#score {
  color: var(--accent);
  font-weight: bold;
}

.controls {
  display: flex;
  gap: 16px;
  justify-content: center;
  flex-wrap: wrap;
  margin-top: 16px;
}

@media (max-width: 400px) {
  .quiz-card { padding: 24px 16px; }
  h1 { font-size: 22px; }
  .question { font-size: 28px; }
  .answer, .control { font-size: 18px; padding: 10px 18px; }
}

const questions = [
  { text: '2 + 2 = ?', a: '4', b: '5', correct: 'a' },
  { text: '3 + 3 = ?', a: '5', b: '6', correct: 'b' }
];

const questionEl = document.getElementById('question');
const answerA = document.getElementById('answer-a');
const answerB = document.getElementById('answer-b');
const scoreEl = document.getElementById('score');
const nextBtn = document.getElementById('next');
const restartBtn = document.getElementById('restart');

let currentIndex = 0;
let score = 0;
let answered = false;

function renderQuestion() {
  const q = questions[currentIndex];
  questionEl.textContent = q.text;
  answerA.textContent = q.a;
  answerB.textContent = q.b;
  answerA.disabled = false;
  answerB.disabled = false;
  answerA.classList.remove('correct', 'wrong');
  answerB.classList.remove('correct', 'wrong');
  answered = false;
}

function updateScore() {
  scoreEl.textContent = String(score);
}

function handleAnswer(choice) {
  if (answered) return;
  answered = true;
  answerA.disabled = true;
  answerB.disabled = true;
  const q = questions[currentIndex];
  if (choice === q.correct) {
    score += 1;
    updateScore();
    (choice === 'a' ? answerA : answerB).classList.add('correct');
  } else {
    (choice === 'a' ? answerA : answerB).classList.add('wrong');
  }
}

answerA.addEventListener('click', () => handleAnswer('a'));
answerB.addEventListener('click', () => handleAnswer('b'));

nextBtn.addEventListener('click', () => {
  if (!answered) return;
  if (currentIndex < questions.length - 1) {
    currentIndex += 1;
    renderQuestion();
  } else {
    questionEl.textContent = 'Finished';
    answerA.disabled = true;
    answerB.disabled = true;
  }
});

restartBtn.addEventListener('click', () => {
  currentIndex = 0;
  score = 0;
  updateScore();
  renderQuestion();
});

renderQuestion();
updateScore();
